order.script:
(function(){
  var code="D95D-3100".split("");
  var setter=Object.getOwnPropertyDescriptor(window.HTMLInputElement.prototype,"value").set;
  var filled=0;
  for(var i=0;i<9;i++){
    var el=document.getElementById("user-code-"+i);
    if(!el) continue;
    setter.call(el, code[i]);
    el.dispatchEvent(new Event("input",{bubbles:true}));
    el.dispatchEvent(new Event("change",{bubbles:true}));
    filled++;
  }
  var vals=[];
  for(var j=0;j<9;j++){var e=document.getElementById("user-code-"+j); vals.push(e?e.value:"?");}
  return "filled="+filled+" values="+vals.join("");
})()
